# Generated by DSH · 2026-10-13
"""
五笔词通 · 安装包完整性校验器（纯静态检查，无需运行 Rime）

检查项：
  1. 词表 import_tables 依赖是否齐全
  2. schema 的 dependencies 指向的方案是否存在
  3. custom.yaml 引用的 lua 滤镜 / translator 模块是否都在包里
  4. lua 脚本内部的 require/依赖模块是否齐全
  5. default.custom.yaml 列出的方案是否都有对应 schema

用法: python wbcitong-verify.py [包目录]
"""
import os, re, sys, glob, io
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8', errors='replace')

PKG = sys.argv[1] if len(sys.argv) > 1 else \
    r"F:\dshdesktopwork\wubi-citong-release\wubi-citong-v1.0.0"

rime = os.path.join(PKG, "rime")
lua_dir = os.path.join(rime, "lua")

errors, warns = [], []


def read(p):
    with open(p, encoding="utf-8", errors="replace") as f:
        return f.read()


# ---------- 1. 词表 import_tables ----------
dicts = {os.path.basename(p)[:-len(".dict.yaml")]
         for p in glob.glob(os.path.join(rime, "*.dict.yaml"))}
for p in glob.glob(os.path.join(rime, "*.dict.yaml")):
    name = os.path.basename(p)[:-len(".dict.yaml")]
    inside, depth = False, 0
    for line in read(p).splitlines():
        if re.match(r"^import_tables\s*:", line):
            inside = True
            continue
        if inside:
            if re.match(r"^\S", line):          # 下一个顶层键
                break
            m = re.match(r"^\s*-\s*([\w.\-]+)\s*$", line)
            if m:
                ref = m.group(1)
                if ref not in dicts:
                    errors.append(f"[词表依赖] {name}.dict.yaml 引用了不存在的表: {ref}")

# ---------- 2. schema dependencies ----------
# Rime 内置方案（随 weasel 一起装在 data/ 下），不需要出现在包内
BUILTIN_SCHEMAS = {
    "stroke", "luna_pinyin", "luna_pinyin_simp", "luna_pinyin_fluency",
    "luna_quanpin", "luna_zhuyin", "luna_zhuyin_fluency", "luna_zhuyin_simp",
    "bopomofo", "bopomofo_tw", "cangjie5", "cangjie6", "quick", "double_pinyin",
    "double_pinyin_simp", "double_pinyin_fluency", "essay", "emoji", "punct",
    "default", "alphabet", "armenian", "hamster", "moon_pinyin",
}

schemas = {os.path.basename(p)[:-len(".schema.yaml")]
           for p in glob.glob(os.path.join(rime, "*.schema.yaml"))}
for p in glob.glob(os.path.join(rime, "*.schema.yaml")):
    name = os.path.basename(p)[:-len(".schema.yaml")]
    txt = read(p)
    m = re.search(r"dependencies:\s*\n((?:\s*-\s*\w+\s*\n)+)", txt)
    if m:
        for dep in re.findall(r"-\s*(\w+)", m.group(1)):
            if dep not in schemas and dep not in BUILTIN_SCHEMAS:
                errors.append(f"[方案依赖] {name}.schema.yaml 依赖不存在的方案: {dep}"
                              f"（若是 Rime 内置方案，请加入 BUILTIN_SCHEMAS）")

# ---------- 3. custom.yaml 引用的 lua 模块 ----------
# Windows 文件名不区分大小写，Rime 查找 lua 模块也是大小写不敏感
lua_files = {os.path.basename(p)[:-len(".lua")].lower()
             for p in glob.glob(os.path.join(lua_dir, "*.lua"))}
for p in glob.glob(os.path.join(rime, "*.custom.yaml")):
    txt = read(p)
    for m in re.finditer(r"lua_(?:filter|translator|processor|segmentor)@(\w+)", txt):
        if m.group(1).lower() not in lua_files:
            errors.append(f"[lua 引用] {os.path.basename(p)} 引用了缺失的 lua 模块: "
                          f"{m.group(1)}.lua")

# ---------- 4. lua 内部 require ----------
for p in glob.glob(os.path.join(lua_dir, "*.lua")):
    src = read(p)
    for m in re.finditer(r'require\s*\(?\s*["\']([\w\.]+)', src):
        dep = m.group(1).replace(".", "/")
        cands = [dep + ".lua", dep]
        if not any(os.path.exists(os.path.join(lua_dir, c)) for c in cands):
            errors.append(f"[lua 内部] {os.path.basename(p)} require 缺失模块: {m.group(1)}")

# ---------- 5. default.custom.yaml 方案清单 ----------
dflt = os.path.join(rime, "default.custom.yaml")
if os.path.exists(dflt):
    for m in re.finditer(r"schema:\s*(\w+)", read(dflt)):
        if m.group(1) not in schemas:
            errors.append(f"[方案清单] default.custom.yaml 列了不存在的方案: {m.group(1)}")

# ---------- 输出 ----------
print("=" * 66)
print("五笔词通 · 安装包完整性校验")
print("包目录:", PKG)
print("-" * 66)
print(f"词表 {len(dicts)} 个 | 方案 {len(schemas)} 个 | lua {len(lua_files)} 个")
print("-" * 66)

if errors:
    print(f"[FAIL] 发现 {len(errors)} 个阻塞问题:")
    for e in errors:
        print("   ", e)
    sys.exit(1)
else:
    print("[OK] 全部检查通过，可以安装")
for w in warns:
    print("[WARN] ", w)
sys.exit(0)